exports.membershipTypeDefs = "\n    type Membership {\n        id: String!\n        memberId: String!\n        userId: String!\n        designationId: String!\n        membershipStatus: String!\n        joiningDate: String!\n        expiryDate: String\n        membershipFee: Float!\n        receiptUrl: String\n        idCardUrl: String\n        appointmentLetterUrl: String\n        qrCode: String\n        renewalDate: String\n        created_at: String!\n        updated_at: String!\n    }\n\n    type MembershipResponse {\n        id: String\n        memberId: String\n        success: Boolean!\n        message: String\n    }\n\n    extend type Query {\n        getMemberships: [Membership!]!\n        getMembershipById(id: String!): Membership\n        getMembershipsByStatus(status: String!): [Membership!]!\n    }\n\n    extend type Mutation {\n        registerMembership(\n            userId: String!\n            designationId: String!\n            membershipFee: Float!\n            designationName: String\n        ): MembershipResponse!\n        \n        renewMembership(membershipId: String!): MembershipResponse!\n        suspendMembership(membershipId: String!): MembershipResponse!\n    }\n";
