exports.eventInternshipTypeDefs = "\n    type Event {\n        id: String!\n        eventId: String!\n        title: String!\n        description: String!\n        eventDate: String!\n        eventEndDate: String\n        location: String!\n        eventType: String!\n        entryFee: Float\n        imageUrl: String\n        organizer: String!\n        registrations: [String!]!\n        registrationCount: Int!\n        status: String!\n    }\n\n    type Internship {\n        id: String!\n        internshipId: String!\n        title: String!\n        description: String!\n        startDate: String!\n        endDate: String!\n        location: String!\n        stipend: Float\n        positions: Int!\n        postedBy: String!\n        applicants: [String!]!\n        selectedInterns: [String!]!\n        status: String!\n    }\n\n    type EventInternshipResponse {\n        id: String\n        success: Boolean!\n        message: String\n    }\n\n    extend type Query {\n        getEvents: [Event!]!\n        getEventById(id: String!): Event\n        getUpcomingEvents: [Event!]!\n        getInternships: [Internship!]!\n        getInternshipById(id: String!): Internship\n    }\n\n    extend type Mutation {\n        createEvent(\n            title: String!\n            description: String!\n            eventDate: String!\n            eventEndDate: String\n            location: String!\n            eventType: String!\n            entryFee: Float\n            imageUrl: String\n        ): EventInternshipResponse!\n        \n        registerForEvent(eventId: String!): EventInternshipResponse!\n        \n        createInternship(\n            title: String!\n            description: String!\n            startDate: String!\n            endDate: String!\n            location: String!\n            stipend: Float\n            positions: Int!\n        ): EventInternshipResponse!\n        \n        applyForInternship(internshipId: String!): EventInternshipResponse!\n        selectIntern(internshipId: String!, userId: String!): EventInternshipResponse!\n    }\n";
exports.enquiryMessageReceiptTypeDefs = "\n    type Enquiry {\n        id: String!\n        name: String!\n        email: String!\n        phone: String!\n        subject: String!\n        message: String!\n        status: String!\n        reply: String\n        repliedBy: String\n        repliedAt: String\n        created_at: String!\n        updated_at: String!\n    }\n\n    type Message {\n        id: String!\n        messageId: String!\n        senderId: String!\n        recipientId: String\n        sendToAll: Boolean!\n        title: String!\n        content: String!\n        imageUrl: String\n        sentDate: String!\n        readBy: [String!]!\n        status: String!\n        scheduledFor: String\n    }\n\n    type Receipt {\n        id: String!\n        receiptId: String!\n        receiptType: String!\n        userId: String!\n        referenceId: String!\n        amount: Float!\n        paymentMethod: String!\n        transactionId: String\n        date: String!\n        pdfUrl: String\n        qrCode: String\n        status: String!\n    }\n\n    type Response {\n        success: Boolean!\n        message: String\n    }\n\n    extend type Query {\n        getEnquiries: [Enquiry!]!\n        getEnquiryById(id: String!): Enquiry\n        getNewEnquiries: [Enquiry!]!\n        getMessages: [Message!]!\n        getMessageById(id: String!): Message\n        getReceipts: [Receipt!]!\n        getUserReceipts: [Receipt!]!\n        getReceiptsByType(type: String!): [Receipt!]!\n    }\n\n    extend type Mutation {\n        submitEnquiry(\n            name: String!\n            email: String!\n            phone: String!\n            subject: String!\n            message: String!\n        ): Response!\n        \n        markEnquiryAsRead(id: String!): Response!\n        replyToEnquiry(id: String!, reply: String!): Response!\n        deleteEnquiry(id: String!): Response!\n        \n        sendMessage(\n            recipientId: String\n            sendToAll: Boolean\n            title: String!\n            content: String!\n            imageUrl: String\n        ): Response!\n        \n        scheduleMessage(\n            recipientId: String\n            sendToAll: Boolean\n            title: String!\n            content: String!\n            imageUrl: String\n            scheduledFor: String!\n        ): Response!\n        \n        deleteMessage(id: String!): Response!\n        \n        createReceipt(\n            receiptType: String!\n            referenceId: String!\n            amount: Float!\n            paymentMethod: String!\n            transactionId: String\n            pdfUrl: String\n            qrCode: String\n        ): Response!\n        \n        voidReceipt(id: String!): Response!\n    }\n";
